; ram_panel_records.s -- the live panel records, RAM 0xf9a0-0xffbe: TLV records {tag, length, payload},
; the ones a .LSW file saves (technics-docs panel-parameter-keys.md).  Each name is a record's payload,
; as SndParam_BlockRamPtrs (ui_widgets/widget_dispatch.s) holds it per tag; tags and lengths are the
; default image's (SndParamRam_DefaultImage).  The table is the same in v5, v6, v7, v9 and v10, so are these
; values.  An operand inside a record is spelled NAME+offset.  Generated by
; scripts/tools/name_kn5000_panel_records.py.
	.equ PANEL_RECORDS,		0xf9a0	; the first record's tag byte: the start of the record run the panel-memory copies move (Mem_Copy of 960 bytes from here to the recall backup PANEL_RECALL_BACKUP)
	.equ PANEL_STYLIST_NAME,	0xf9a2	; tag 0x78, 18 bytes: 16-character name of the selected Music Stylist style (EffectMode_DisplayName_Render copies it), then 2 bytes
	.equ PANEL_PART_RT1,		0xf9b6	; tag 0x00, 24 bytes: part record (mixer channel RT1)
	.equ PANEL_PART_RT2,		0xf9d0	; tag 0x01, 24 bytes: part record (mixer channel RT2)
	.equ PANEL_PART_LEFT,		0xf9ea	; tag 0x02, 24 bytes: part record (mixer channel LEFT)
	.equ PANEL_PART_PT4,		0xfa04	; tag 0x03, 24 bytes: part record (mixer channel PT4)
	.equ PANEL_PART_PT5,		0xfa1e	; tag 0x04, 24 bytes: part record (mixer channel PT5)
	.equ PANEL_PART_PT6,		0xfa38	; tag 0x05, 24 bytes: part record (mixer channel PT6)
	.equ PANEL_PART_PT7,		0xfa52	; tag 0x06, 24 bytes: part record (mixer channel PT7)
	.equ PANEL_PART_PT8,		0xfa6c	; tag 0x07, 24 bytes: part record (mixer channel PT8)
	.equ PANEL_PART_PT9,		0xfa86	; tag 0x08, 24 bytes: part record (mixer channel PT9)
	.equ PANEL_PART_PT10,		0xfaa0	; tag 0x09, 24 bytes: part record (mixer channel PT10)
	.equ PANEL_PART_PT11,		0xfaba	; tag 0x0a, 24 bytes: part record (mixer channel PT11)
	.equ PANEL_PART_PT12,		0xfad4	; tag 0x0b, 24 bytes: part record (mixer channel PT12)
	.equ PANEL_PART_PT13,		0xfaee	; tag 0x0c, 24 bytes: part record (mixer channel PT13)
	.equ PANEL_PART_PT14,		0xfb08	; tag 0x0d, 24 bytes: part record (mixer channel PT14)
	.equ PANEL_PART_PT15,		0xfb22	; tag 0x0e, 24 bytes: part record (mixer channel PT15)
	.equ PANEL_PART_PT16,		0xfb3c	; tag 0x0f, 24 bytes: part record (mixer channel PT16)
	.equ PANEL_PART_ACP1,		0xfb56	; tag 0x10, 24 bytes: part record (mixer channel ACP1)
	.equ PANEL_PART_ACP2,		0xfb70	; tag 0x11, 24 bytes: part record (mixer channel ACP2)
