	.equ PANEL_PART_RTBS,		0xfbf2	; tag 0x16, 24 bytes: part record (mixer channel RTBS)
	.equ PANEL_PART_CTRL,		0xfc0c	; tag 0x19, 24 bytes: part record (mixer channel CTRL)
	.equ PANEL_DRAWBAR_RIGHT1,	0xfc26	; tag 0x44, 10 bytes: the RIGHT 1 drawbar registration (parameter ids 0x82nn)
	.equ PANEL_DRAWBAR_RIGHT2,	0xfc32	; tag 0x45, 10 bytes: the RIGHT 2 drawbar registration (parameter ids 0x86nn)
	.equ PANEL_DRAWBAR_LEFT,	0xfc3e	; tag 0x46, 10 bytes: the LEFT drawbar registration (parameter ids 0x8Ann)
	.equ PANEL_VOCALIST,		0xfc4a	; tag 0x47, 8 bytes: the Vocalist settings (chordal / vocoder ignore, MIDI channel, program, harmony, key sends ...)
	.equ PANEL_MIC,			0xfc54	; tag 0x43, 4 bytes: MIC reverb on/off, mute, volume
	.equ PANEL_STYLE,		0xfc5a	; tag 0x48, 10 bytes: style number (+0), bank (+1), APC memory / mode (+3), TechniChord on/off (+4), fill-in / ending / synchro break (+5), tempo (+8)
	.equ PANEL_CONDUCTOR,		0xfc66	; tag 0x90, 6 bytes: conductor (+0), APC on bass / left hold (+3), R1R2 octave (+4)
	.equ PANEL_EFFECT_SWITCHES,	0xfc6e	; tag 0x60, 4 bytes: acoustic illusion / equalizer / reverb on/off (+1)
	.equ PANEL_DSP_EFFECT,		0xfc74	; tag 0x61, 24 bytes: DSP effect algorithm (+0) and its parameters
	.equ PANEL_DIGITAL_REVERB,	0xfc8e	; tag 0x63, 24 bytes: digital reverb algorithm (+0) and its parameters
	.equ PANEL_EQUALIZER,		0xfca8	; tag 0x64, 24 bytes: equalizer algorithm (+0) and its parameters
	.equ PANEL_ACOUSTIC_ILLUSION,	0xfcc2	; tag 0x65, 24 bytes: acoustic illusion algorithm (+0) and its parameters
