	.equ PANEL_REC_68,		0xfcf6	; tag 0x68, 10 bytes: keys not identified
	.equ PANEL_PLAY_SETTINGS,	0xfd02	; tag 0x70, 8 bytes: rotary speed, split point (+0/+1), transpose (+2), orchestrator (+3), TechniChord type (+4), fade in / out time (+5/+6)
	.equ PANEL_MSP,			0xfd0c	; tag 0x72, 14 bytes: MSP mute / volume (+3), reverb (+7)
	.equ PANEL_SCALE_TUNE,		0xfd1c	; tag 0x92, 14 bytes: scale tune type (+0), key / on-off (+1), user notes (+2..)
	.equ PANEL_PMEMOUT_L,		0xfd2c	; tag 0x71, 2 bytes: the PANEL MEMORY page's ON/OFF cell, bit 1 of +0 (PmemOutLGridCheck; it gates the drawbar re-post of BitMapOut_Snapshot_PostProcess)
	.equ PANEL_FOOT_CONTROLLERS,	0xfd30	; tag 0x99, 30 bytes: expression pedal (+2), foot switches 1-2 (+4/+5), foot controller switches 1-4 (+6..+9)
	.equ PANEL_MIDI,		0xfd50	; tag 0x80, 14 bytes: MIDI settings: common (note only, program change mode / to panel memory), MIDI OUT, realtime clock ... bits 0-1 of +0 = the MIDI mode
	.equ PANEL_PART_MSP,		0xfd62	; tag 0x17, 24 bytes: part record (mixer channel MSP)
	.equ PANEL_PART_18,		0xfd7c	; tag 0x18, 24 bytes: part record of tag 0x18 (no mixer channel)
	.equ PANEL_PMEM_SETTINGS,	0xfd96	; tag 0x98, 18 bytes: panel memory mode / number (+0/+1), music style arranger (+3), metronome mute / volume (+4), panel memory filter (+7)
	.equ PANEL_GM,			0xfdaa	; tag 0x91, 10 bytes: GM on/off (+3)
	.equ PANEL_TOUCH,		0xfdb6	; tag 0x93, 34 bytes: initial touch velocity sense (+0), after touch curve (+5), on/off and threshold (+6)
